const root=document.querySelector('#app'),toast=document.querySelector('#toast');
const state={page:'home',recruiter:null,candidate:null,job:null};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const logo='<img class="brand-logo" src="/assets/logo_header.png" alt="ICD Platform">';
function note(message,kind='ok'){toast.textContent=message;toast.dataset.kind=kind;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}}),body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.detail||'Please try again.');return body}
function show(html){root.innerHTML=html;window.scrollTo({top:0,behavior:'instant'})}
function mark(c){return c?.logo_base64?`<img src="data:image/png;base64,${c.logo_base64}" alt="${esc(c.name)}">`:`<span>${esc((c?.name||'I')[0])}</span>`}

function welcome(){show(`<main class="landing">
  <nav class="landing-nav">${logo}<div class="nav-links"><a href="#platform">Platform</a><a href="#workflow">How it works</a><span>Intelligent Candidate Discovery</span></div></nav>
  <section class="landing-hero"><div class="hero-copy"><div class="kicker">One intelligent hiring workspace</div><h1>Great people.<br><em>Clearer decisions.</em></h1><p>ICD brings job discovery, evidence-led screening, structured interviews, and hiring decisions into one fast, secure experience.</p><div class="hero-actions"><button class="primary candidate-go">Explore opportunities <b>→</b></button><button class="secondary recruiter-go">Open recruiter workspace</button></div><div class="hero-proof"><span><b>Faster</b> resume review</span><span><b>Consistent</b> evaluation</span><span><b>Secure</b> candidate data</span></div></div>
  <div class="product-stage"><div class="stage-bar"><i></i><span>Live candidate intelligence</span><b>Role: Product Engineer</b></div><div class="match-card"><div class="avatar">AK</div><div><b>Arun Kumar</b><span>Senior Developer · 5 years</span></div><strong>92</strong></div><div class="signal-grid"><div><span>Skills match</span><b>94%</b><i><em style="width:94%"></em></i></div><div><span>Experience fit</span><b>89%</b><i><em style="width:89%"></em></i></div><div><span>Education</span><b>90%</b><i><em style="width:90%"></em></i></div></div><div class="stage-footer"><span>✓ Evidence verified</span><button>Shortlist candidate</button></div></div></section>
  <section class="impact-strip"><div><strong>One profile</strong><span>for every application</span></div><div><strong>Role-wise</strong><span>screening and reports</span></div><div><strong>End-to-end</strong><span>from job to offer</span></div><div><strong>Always clear</strong><span>live candidate status</span></div></section>
  <section class="platform-section" id="platform"><div class="section-intro"><div class="kicker">Designed around better decisions</div><h2>Every hiring moment, beautifully connected.</h2><p>Purpose-built experiences for candidates and hiring teams, sharing one reliable source of truth.</p></div><div class="bento"><article class="bento-large"><div class="bento-icon">◎</div><span>Intelligent screening</span><h3>Turn every résumé into clear, comparable evidence.</h3><div class="mini-chart"><i style="height:45%"></i><i style="height:68%"></i><i style="height:54%"></i><i style="height:88%"></i><i style="height:75%"></i></div></article><article><div class="bento-icon violet">◇</div><span>Candidate experience</span><h3>Apply once. Track every step.</h3><p>Verified jobs, reusable profiles, and transparent application status.</p></article><article><div class="bento-icon green">✓</div><span>Structured hiring</span><h3>Move confidently from shortlist to offer.</h3><p>Interviews, decisions, role reports, and offers stay aligned.</p></article></div></section>
  <section class="journey" id="workflow"><div class="section-intro"><div class="kicker">One simple journey</div><h2>From opening to offer—without the busywork.</h2></div><div class="journey-steps"><article><b>01</b><div><h3>Publish</h3><p>Create detailed roles and share them through a polished public application page.</p></div></article><article><b>02</b><div><h3>Discover</h3><p>Candidates find verified opportunities and apply with a reusable secure profile.</p></div></article><article><b>03</b><div><h3>Evaluate</h3><p>Screen multiple résumés quickly with consistent role-specific evidence.</p></div></article><article><b>04</b><div><h3>Decide</h3><p>Coordinate interviews, selection reports, and offers from one workspace.</p></div></article></div></section>
  <section class="landing-proof"><div class="section-intro"><div class="kicker">Built for every hiring decision</div><h2>More signal. Less administration.</h2><p>ICD keeps every role, candidate, conversation, and decision connected—so hiring teams spend time evaluating people, not chasing files.</p></div><div class="proof-grid"><article><i>⌁</i><h3>Evidence-first screening</h3><p>Compare skills, experience, education, strengths, and gaps against the exact requirements of each role.</p><span>Explainable scores · Ranked talent</span></article><article><i>◷</i><h3>Structured interviews</h3><p>Generate grounded interview questions, schedule conversations, capture notes, and track decisions consistently.</p><span>AI preparation · Shared workflow</span></article><article><i>↗</i><h3>Role-wise intelligence</h3><p>See conversion from screening to shortlist, interview, selection, and offer for every open position.</p><span>Live reports · Pipeline clarity</span></article><article><i>◇</i><h3>Professional offers</h3><p>Create personalized, company-branded offer letters for multiple selected candidates in one workflow.</p><span>Bulk generation · Secure PDFs</span></article></div></section>
  <section class="landing-security"><div><div class="kicker pale">Private by design</div><h2>Candidate trust is part of the product.</h2><p>Email verification, company-scoped workspaces, and role-based access help keep candidate information visible only to the people who should see it.</p></div><div class="security-list"><span><i>✓</i><b>Password-free candidate verification</b></span><span><i>✓</i><b>Private recruiter workspaces</b></span><span><i>✓</i><b>Company-scoped candidate records</b></span><span><i>✓</i><b>Transparent application progress</b></span></div></section>
  <section class="choice"><div><div class="kicker pale">Choose your experience</div><h2>Where talent and opportunity meet.</h2><p>Whether you are looking for your next role or building your next team, ICD keeps the journey simple and transparent.</p></div><div class="choice-cards"><button class="candidate-go"><span>For candidates</span><b>Find your next role</b><em>Browse verified openings →</em></button><button class="recruiter-go"><span>For hiring teams</span><b>Build the right team</b><em>Enter your workspace →</em></button></div></section>
  <footer>${logo}<span>Intelligent Candidate Discovery Platform</span><small>Fast · Secure · Evidence-led</small></footer>
</main>`);document.querySelectorAll('.candidate-go').forEach(b=>b.onclick=candidateEntry);document.querySelectorAll('.recruiter-go').forEach(b=>b.onclick=recruiterGate)}

async function recruiterGate(){let orgs=[];try{orgs=await api('/api/organizations')}catch(e){note(e.message,'error')}show(`<main class="auth-layout recruiter-access"><section class="auth-story"><div class="auth-brand">${logo}<span>Recruiter workspace</span></div><div class="access-preview"><div class="preview-top"><span>Hiring command centre</span><i>Live</i></div><div class="preview-kpis"><div><b>48</b><span>Candidates</span></div><div><b>14</b><span>Shortlisted</span></div><div><b>06</b><span>Interviews</span></div></div><div class="preview-pipeline"><span>Screened</span><i><em style="width:100%"></em></i><span>Shortlisted</span><i><em style="width:62%"></em></i><span>Selected</span><i><em style="width:28%"></em></i></div></div><div class="story-copy"><div class="kicker pale">Evidence-led hiring</div><h1>Build the right team, faster.</h1><p>Screen consistently, coordinate every stage, and keep your team aligned from opening to offer.</p><div class="story-points"><span>✓ AI-assisted screening</span><span>✓ One connected workspace</span><span>✓ Private company access</span></div></div></section><section class="auth-panel"><div class="auth-panel-top"><button class="back" id="back">← Back to home</button><span class="step-count">01 / 02</span></div><div class="kicker">Organization access</div><h2>Choose your company</h2><p>Select your organization to open its secure recruiter workspace.</p><div class="search-wrap"><span>⌕</span><input id="org-search" placeholder="Search organizations"></div><div class="org-grid" id="org-list">${orgs.map(orgCard).join('')}</div><div id="access" class="access-box" hidden><div class="access-heading"><div><b>Secure access</b><span>Enter your organization code</span></div><i>02</i></div><label>Access code</label><input id="code" inputmode="numeric" placeholder="Enter access code"><button class="primary full" id="login">Continue to workspace →</button></div></section></main>`);document.querySelector('#back').onclick=welcome;bindOrgs();document.querySelector('#org-search').oninput=e=>{document.querySelector('#org-list').innerHTML=orgs.filter(o=>o.name.toLowerCase().includes(e.target.value.toLowerCase())).map(orgCard).join('');bindOrgs()};function bindOrgs(){document.querySelectorAll('[data-org]').forEach(card=>card.onclick=()=>{document.querySelectorAll('[data-org]').forEach(x=>x.classList.remove('selected'));card.classList.add('selected');state.org=card.dataset.org;document.querySelector('#access').hidden=false;document.querySelector('#access').scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector('#code').focus()});const login=document.querySelector('#login');if(login)login.onclick=async()=>{try{await api('/api/session/recruiter',{method:'POST',body:JSON.stringify({company_id:state.org,access_code:document.querySelector('#code').value})});loadRecruiter()}catch(e){note(e.message,'error')}}}}
function orgCard(o){return `<button class="org-card" data-org="${esc(o.id)}"><div class="company-mark">${mark(o)}</div><b>${esc(o.name)}</b><span>${esc(o.industry||'Organization')}</span></button>`}

async function candidateEntry(){try{state.candidate=await api('/api/candidate/me');candidatePortal();return}catch(_){}show(`<main class="candidate-auth candidate-access"><section class="candidate-auth-card"><div class="auth-panel-top"><div class="auth-brand small">${logo}<span>Candidate portal</span></div><button class="back" id="back">← Back to home</button></div><div class="candidate-copy"><div class="kicker">Secure candidate access</div><h1>Your next role starts here.</h1><p>Sign in with a one-time email code. No password to remember, and your secure session stays active on this device.</p></div><div id="otp" class="otp-card"><label>Email address</label><div class="email-field"><span>✉</span><input id="email" type="email" placeholder="name@example.com"></div><button class="primary full" id="send">Send verification code →</button><small>We will only use your email to verify your identity and update your applications.</small></div><div class="security-note"><i>✓</i><span><b>Private by design</b>Your information is shared only with companies you apply to.</span></div></section><aside><div class="candidate-preview"><div class="preview-head"><span>Your candidate journey</span><b>Simple & transparent</b></div><div class="journey-card done"><i>✓</i><div><b>Create one profile</b><span>Keep your information ready</span></div></div><div class="journey-line"></div><div class="journey-card active"><i>2</i><div><b>Discover verified roles</b><span>Explore trusted opportunities</span></div></div><div class="journey-line muted"></div><div class="journey-card"><i>3</i><div><b>Track live progress</b><span>Know where every application stands</span></div></div><div class="candidate-highlight"><span>One secure profile</span><strong>Apply faster.<br>Stay informed.</strong></div></div></aside></main>`);document.querySelector('#back').onclick=welcome;document.querySelector('#send').onclick=async()=>{const email=document.querySelector('#email').value.trim();try{await api('/api/candidate/send-otp',{method:'POST',body:JSON.stringify({email})});document.querySelector('#otp').innerHTML=`<div class="notice">Verification code sent to <b>${esc(email)}</b></div><label>Enter your verification code</label><div class="email-field"><span>●</span><input id="token" inputmode="numeric" autocomplete="one-time-code" placeholder="Code from your email"></div><button class="primary full" id="verify">Verify and continue →</button><button class="text-button" id="change-email">Use a different email</button>`;document.querySelector('#change-email').onclick=candidateEntry;document.querySelector('#verify').onclick=async()=>{try{await api('/api/candidate/verify-otp',{method:'POST',body:JSON.stringify({email,token:document.querySelector('#token').value})});state.candidate=await api('/api/candidate/me');candidatePortal()}catch(e){note(e.message,'error')}}}catch(e){note(e.message,'error')}}}
function candidatePortal(){const c=state.candidate;if(!c.profile)return profile();const applied=new Set(c.applications.map(a=>String(a.job_id)));show(`<main class="portal"><header class="portal-head">${logo}<div class="identity"><b>${esc(c.profile.full_name)}</b><span>${esc(c.email)}</span></div><button class="secondary" id="signout">Sign out</button></header><section class="candidate-banner"><div class="kicker pale">Welcome back, ${esc(c.profile.full_name.split(' ')[0])}</div><h1>Discover roles built for your skills.</h1><p>Explore verified openings, apply securely, and follow every application in one place.</p></section><div class="tabs"><button class="active" data-tab="jobs">Find jobs</button><button data-tab="apps">My applications (${c.applications.length})</button></div><section id="candidate-view"></section></main>`);document.querySelector('#signout').onclick=async()=>{await api('/api/candidate/session',{method:'DELETE'});state.candidate=null;welcome()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));b.dataset.tab==='jobs'?jobs(c.jobs,applied):applications(c.applications)});jobs(c.jobs,applied)}
function profile(){show(`<main class="simple-page profile-page"><header class="profile-brand">${logo}<span>Candidate portal</span></header><section class="form-card"><div class="profile-progress"><i><em></em></i><span>Profile setup · Almost there</span></div><div class="kicker">Your candidate profile</div><h1>Tell us about yourself.</h1><p>Complete this once and we will reuse the information whenever you apply.</p><div class="form-grid"><div><label>Full name</label><input id="name" placeholder="Your full name"></div><div><label>Verified email</label><input value="${esc(state.candidate.email)}" disabled></div><div class="wide"><label>Phone number <small>Optional</small></label><input id="phone" placeholder="Your contact number"></div></div><div class="profile-footer"><div><b>Secure profile</b><span>Your data stays private until you apply.</span></div><button class="primary" id="save">Save and explore jobs →</button></div></section></main>`);document.querySelector('#save').onclick=async()=>{try{await api('/api/candidate/profile',{method:'PUT',body:JSON.stringify({full_name:document.querySelector('#name').value,phone:document.querySelector('#phone').value})});state.candidate=await api('/api/candidate/me');candidatePortal()}catch(e){note(e.message,'error')}}}
function jobs(items,applied){const view=document.querySelector('#candidate-view');view.innerHTML=`<div class="section-title"><div><div class="kicker">Verified openings</div><h2>Open positions (${items.length})</h2></div><input id="search" placeholder="Search role or company"></div><div class="public-jobs" id="job-list">${items.map(j=>jobCard(j,applied)).join('')||'<div class="empty">No published roles yet.</div>'}</div>`;document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelector('#job-list').innerHTML=items.filter(j=>`${j.title} ${j.company?.name}`.toLowerCase().includes(q)).map(j=>jobCard(j,applied)).join('');bindJobs()};bindJobs()}
function jobCard(j,applied){const done=applied.has(String(j.id));return `<article class="public-job"><div class="company-row"><div class="company-mark">${mark(j.company)}</div><div><b>${esc(j.company?.name||'Hiring organization')}</b><span>${esc(j.company?.industry||'Careers')}</span></div></div><h3>${esc(j.title)}</h3><p>${esc([j.location,j.employment_type,j.experience_level].filter(Boolean).join(' · '))}</p><div class="chips">${(j.required_skills||[]).slice(0,5).map(s=>`<span>${esc(s)}</span>`).join('')}</div><button class="${done?'secondary':'primary'} full" data-job="${j.id}" ${done?'disabled':''}>${done?'Applied':'View and apply'}</button></article>`}
function bindJobs(){document.querySelectorAll('[data-job]').forEach(b=>b.onclick=async()=>{try{state.job=await api('/api/public/jobs/'+b.dataset.job);jobDetail()}catch(e){note(e.message,'error')}})}
function jobDetail(){const j=state.job,p=state.candidate.profile;show(`<main class="job-detail"><button class="back" id="back-jobs">← Back to jobs</button><section class="job-company"><div class="company-mark large">${mark(j.company)}</div><div><div class="kicker">${esc(j.company?.name||'Hiring organization')}</div><h1>${esc(j.title)}</h1><p>${esc([j.location,j.employment_type,j.experience_level].filter(Boolean).join(' · '))}</p></div></section><div class="detail-grid"><article><h2>About this role</h2><p>${esc(j.description||'More details will be shared by the hiring team.')}</p><h2>What you will do</h2><p>${esc(j.responsibilities||'Responsibilities will be discussed with shortlisted candidates.')}</p><h2>What we offer</h2><p>${esc(j.benefits||'A supportive workplace and opportunities to grow.')}</p></article><form id="apply"><h2>Your application</h2><p>Your resume is shared only with this hiring organization.</p><label>Full name</label><input name="full_name" value="${esc(p.full_name)}" required><label>Phone</label><input name="phone" value="${esc(p.phone||'')}"><label>Resume · PDF or DOCX</label><input name="resume" type="file" accept=".pdf,.docx" required><button class="primary full">Submit application</button></form></div></main>`);document.querySelector('#back-jobs').onclick=candidatePortal;document.querySelector('#apply').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);fd.append('job_id',j.id);try{await api('/api/candidate/applications',{method:'POST',body:fd});note('Application submitted');state.candidate=await api('/api/candidate/me');candidatePortal()}catch(err){note(err.message,'error')}}}
function applications(items){document.querySelector('#candidate-view').innerHTML=`<div class="section-title"><div><div class="kicker">Your progress</div><h2>My applications</h2></div></div><div class="application-list">${items.map(a=>`<article><div><h3>${esc(a.jobs?.title||'Job application')}</h3><p>${esc([a.jobs?.location,a.jobs?.employment_type,new Date(a.applied_at).toLocaleDateString()].filter(Boolean).join(' · '))}</p><small>${esc(a.resume_filename)}</small></div><span class="status">${esc(a.status||'Submitted')}</span></article>`).join('')||'<div class="empty">You have not applied yet.</div>'}</div>`}

const names={home:'Overview',jobs:'Jobs',screening:'Resume screening',candidates:'Candidates',interviews:'Interviews',reports:'Reports',offers:'Offer letters',insights:'AI insights'};
async function loadRecruiter(){try{state.recruiter=await api('/api/bootstrap');renderRecruiter()}catch(_){recruiterGate()}}
function renderRecruiter(){const co=state.recruiter.company,content=state.page==='home'?dashboard():state.page==='jobs'?jobManagement():state.page==='screening'?screening():state.page==='candidates'?candidateCards():state.page==='interviews'?interviewPage():state.page==='reports'?reportPage():state.page==='offers'?offerPage():insightsPage(),nav=(keys)=>keys.map(k=>{const icons={home:'⌂',jobs:'▣',screening:'⌁',candidates:'◎',interviews:'◷',reports:'↗',offers:'◇',insights:'✦'};return `<button data-page="${k}" class="${state.page===k?'active':''}"><i>${icons[k]}</i><span>${names[k]}</span>${state.page===k?'<em></em>':''}</button>`}).join('');show(`<div class="workspace"><aside><div class="company-sidebar-brand"><div class="company-mark">${mark(co)}</div><div><small>Signed in as</small><b>${esc(co.name||'Organization')}</b><span>${esc(co.industry||'Recruiter workspace')}</span></div></div><nav><small>Workspace</small>${nav(['home','jobs','screening','candidates'])}<small>Hiring operations</small>${nav(['interviews','reports','offers'])}<small>Intelligence</small>${nav(['insights'])}</nav><div class="sidebar-footer"><div class="workspace-help"><i>✦</i><div><b>AI workspace</b><span>Screen, compare and prepare interviews with evidence.</span></div></div><button class="secondary full" id="logout">↪ Sign out of ${esc(co.name||'company')}</button></div></aside><main><header class="workspace-head"><div><div class="kicker">${esc(co.name)} · Recruiter workspace</div><h1>${names[state.page]}</h1><p>${{home:'See priorities, pipeline health, and the next best actions.',jobs:'Create, publish and manage every opportunity.',screening:'Evaluate every résumé against one consistent role.',candidates:'Compare talent with clear evidence and confidence.',interviews:'Keep every conversation organized and on time.',reports:'Understand progress and outcomes role by role.',offers:'Prepare professional offers for selected candidates.',insights:'Turn your hiring data into useful answers.'}[state.page]}</p></div><div class="header-actions"><span class="online"><i></i> Live workspace</span><button data-page="screening">＋ Screen résumés</button></div></header>${content}</main></div>`);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderRecruiter()});document.querySelector('#logout').onclick=async()=>{await api('/api/session',{method:'DELETE'});state.recruiter=null;welcome()};bindRecruiter()}
function dashboard(){const s=state.recruiter.summary,cs=state.recruiter.candidates||[],top=[...cs].sort((a,b)=>b.score-a.score).slice(0,4),apps=state.recruiter.applications||[],conversion=s.candidates?Math.round(s.selected/s.candidates*100):0;return `<section class="overview-welcome"><div><div class="kicker pale">Today’s hiring focus</div><h2>Move the right candidates forward.</h2><p>Your workspace has <b>${s.shortlisted}</b> shortlisted candidates and <b>${s.scheduled_interviews}</b> upcoming interviews.</p><div><button class="primary" data-quick="screening">Screen new résumés →</button><button class="secondary light" data-quick="candidates">Review talent</button></div></div><div class="overview-signal"><span>Selection conversion</span><strong>${conversion}%</strong><i><em style="width:${conversion}%"></em></i><small>${s.selected} selected from ${s.candidates} screened</small></div></section><div class="stats premium-stats">${[['Active roles',s.active_jobs,'▣'],['Applications',apps.length,'↧'],['Screened',s.candidates,'◎'],['Shortlisted',s.shortlisted,'★'],['Interviews',s.scheduled_interviews,'◷']].map(([k,v,i])=>`<article><i>${i}</i><div><span>${k}</span><strong>${v}</strong><small>Live workspace total</small></div></article>`).join('')}</div><div class="dashboard-grid overview-grid"><section class="panel pipeline-panel"><div class="panel-heading"><div><div class="kicker">Live pipeline</div><h2>Candidate conversion</h2></div><button class="text-button" data-quick="reports">Full report →</button></div>${bars([['Screened',s.candidates],['Shortlisted',s.shortlisted],['Interview',s.scheduled_interviews],['Selected',s.selected]],Math.max(1,s.candidates))}</section><section class="panel action-panel"><div class="kicker">Quick actions</div><h2>Keep hiring moving</h2><button data-quick="jobs"><span>＋</span><div><b>Create or manage a role</b><small>Publish and update openings</small></div><em>→</em></button><button data-quick="screening"><span>⌁</span><div><b>Screen candidate résumés</b><small>Evaluate against one role</small></div><em>→</em></button><button data-quick="offers"><span>◇</span><div><b>Prepare offer letters</b><small>Personalized, ready to send</small></div><em>→</em></button></section></div><section class="panel top-talent"><div class="panel-heading"><div><div class="kicker">Top matches</div><h2>Candidates worth reviewing</h2></div><button class="text-button" data-quick="candidates">View all →</button></div><div class="top-talent-grid">${top.map(c=>`<article><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><div><b>${esc(c.candidate_name||c.filename)}</b><span>${esc(c.job_role||'Role not assigned')}</span></div><strong>${c.score}<small>%</small></strong></article>`).join('')||'<div class="designed-empty"><p>Screen résumés to surface your strongest matches.</p></div>'}</div></section>`}
function bars(items,total){return items.map(([k,v])=>`<div class="metric"><label>${esc(k)}<b>${v}</b></label><i><span style="width:${total?Math.max(2,v/total*100):0}%"></span></i></div>`).join('')}
function jobManagement(){const apps=state.recruiter.applications||[];return `<div class="section-title"><div><div class="kicker">Role library</div><h2>${state.recruiter.jobs.length} job postings</h2></div><button class="primary" id="new-job">＋ Create job</button></div><div class="recruiter-cards job-admin-cards">${state.recruiter.jobs.map(j=>{const count=apps.filter(a=>String(a.job_id)===String(j.id)).length;return `<article><div class="card-top"><span class="status">${esc(j.status||'active')}</span><span>${count} application${count===1?'':'s'}</span></div><h3>${esc(j.title)}</h3><p>${esc([j.department,j.location,j.employment_type].filter(Boolean).join(' · '))}</p><div class="chips">${(j.required_skills||[]).slice(0,7).map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="row"><button class="secondary" data-screen="${j.id}">Screen résumés</button><button class="secondary" data-job-apps="${j.id}">Applications</button><button class="icon-action danger" title="Delete job" data-delete-job="${j.id}">⌫</button></div></article>`}).join('')}</div><section class="panel applications-panel" id="applications-panel"><div class="section-title"><div><div class="kicker">Incoming talent</div><h2>Applied candidates (${apps.length})</h2></div></div>${applicationAdmin(apps)}</section>`}
function applicationAdmin(items){return `<div class="application-admin">${items.map(a=>`<article data-app-row="${a.id}"><div class="candidate-monogram">${esc((a.applicant_name||'C')[0])}</div><div><h3>${esc(a.applicant_name||'Candidate')}</h3><p>${esc(a.applicant_email||'')} · ${esc(state.recruiter.jobs.find(j=>String(j.id)===String(a.job_id))?.title||'Job')}</p><small>${a.applied_at?new Date(a.applied_at).toLocaleString():''} · ${esc(a.resume_filename||'No résumé')}</small></div><select data-app-status="${a.id}">${['Submitted','Screening','Shortlisted','Interview','Selected','Rejected'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select><a class="secondary button-link" href="/api/applications/${a.id}/resume">Download</a><button class="icon-action danger" title="Remove application" data-delete-app="${a.id}">⌫</button></article>`).join('')||'<div class="designed-empty"><i>◎</i><h3>No applications yet</h3><p>Published jobs and QR links will bring candidate applications here.</p></div>'}</div>`}
function screening(){const active=state.recruiter.jobs.filter(j=>j.status==='active');return `<div class="screening-intro"><div><div class="kicker">AI-assisted evaluation</div><h2>Turn résumés into comparable evidence.</h2><p>Choose a role, confirm what matters, then upload multiple candidates. ICD extracts, scores, and ranks every résumé consistently.</p></div><div class="screening-badges"><span>✓ Parallel processing</span><span>✓ Evidence grounded</span><span>✓ PDF & DOCX</span></div></div><div class="screening-steps"><span class="active"><i>1</i>Role criteria</span><em></em><span><i>2</i>Candidate files</span><em></em><span><i>3</i>Ranked results</span></div><form id="screen-form" class="screening-layout"><section class="panel criteria-card"><div class="panel-heading"><div><div class="kicker">01 · Define the benchmark</div><h2>What does success look like?</h2></div><span class="step-badge">Required</span></div><label>Select an active job</label><select id="job" class="native-job-select" aria-hidden="true"><option value="">Choose a job or enter criteria manually</option>${active.map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join('')}</select><div class="job-picker" id="job-picker"><button type="button" class="job-picker-trigger" id="job-picker-trigger"><i>▣</i><span><small>Screen candidates for</small><b>Choose an active job</b></span><em>⌄</em></button><div class="job-picker-menu" id="job-picker-menu" hidden><div class="job-picker-search"><i>⌕</i><input id="job-picker-search" placeholder="Search roles or departments" autocomplete="off"></div><button type="button" class="job-option manual" data-job-option=""><i>＋</i><span><b>Enter criteria manually</b><small>Create a one-time screening benchmark</small></span></button><div class="job-option-list" id="job-option-list">${active.map(j=>jobPickerOption(j)).join('')}</div></div></div><div class="selected-role-preview" id="selected-role-preview"><i>✦</i><div><b>${active.length} active role${active.length===1?'':'s'} available</b><span>Selecting a job automatically loads its title, skills, responsibilities, and requirements.</span></div></div><label>Role title</label><input id="role" required placeholder="e.g. Senior Backend Engineer"><label>Requirements and priorities</label><textarea id="details" rows="8" placeholder="Describe must-have skills, experience, responsibilities, and preferred qualifications..."></textarea><div class="criteria-tip"><i>✦</i><div><b>Better criteria, better ranking</b><span>Be specific about required skills and experience. The AI uses only the evidence you provide.</span></div></div></section><section class="panel upload-card"><div class="panel-heading"><div><div class="kicker">02 · Add candidates</div><h2>Upload résumés</h2></div><span class="step-badge">Up to 20 MB</span></div><label class="upload premium-upload"><input id="files" type="file" multiple accept=".pdf,.docx" required><i>⇧</i><b>Choose résumé files</b><span>Drag and drop or browse from your device</span><small>PDF or DOCX · Select multiple candidates together</small></label><div class="screening-checks"><div><i>1</i><span><b>Extract</b><small>Read skills and experience</small></span></div><div><i>2</i><span><b>Evaluate</b><small>Compare with role evidence</small></span></div><div><i>3</i><span><b>Rank</b><small>Produce explainable scores</small></span></div></div><button class="primary full screen-submit">✦ Start intelligent screening</button><p id="screen-status" class="screen-status"></p></section></form>`}
function jobPickerOption(j){return `<button type="button" class="job-option" data-job-option="${j.id}" data-search="${esc(`${j.title} ${j.department||''} ${j.location||''}`.toLowerCase())}"><i>${esc((j.title||'J')[0])}</i><span><b>${esc(j.title)}</b><small>${esc([j.department,j.location,j.employment_type].filter(Boolean).join(' · ')||'Active role')}</small></span><em>${(j.required_skills||[]).length} skills</em></button>`}
function candidateCards(){const cs=state.recruiter.candidates;return `<div class="section-title"><div><div class="kicker">Evidence-ranked talent</div><h2>${cs.length} screened candidates</h2></div><div class="candidate-filters"><button class="view-chip active">All</button><span>${cs.filter(c=>c.score>=70).length} recommended</span></div></div><div class="recruiter-cards talent-cards">${cs.map(c=>`<article><div class="card-top"><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><div class="score-ring" style="--score:${Math.max(0,Math.min(100,c.score))}"><b>${c.score}</b><span>match</span></div></div><div class="kicker">${esc(c.job_role||'Candidate')}</div><h3>${esc(c.candidate_name||c.filename)}</h3><p>${esc([c.years_experience,c.education].filter(Boolean).join(' · '))}</p><div class="chips">${(c.matched_skills||c.skills||[]).slice(0,6).map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="candidate-evidence"><span><b>${(c.matched_skills||[]).length}</b> matched skills</span><span><b>${(c.gaps||[]).length}</b> gaps</span><span class="status">${esc(c.decision_status)}</span></div><div class="row"><button class="secondary" data-view-candidate="${c.id}">View evidence</button><button class="secondary" data-status="Selected" data-id="${c.id}">Select</button><button class="danger" data-status="Rejected" data-id="${c.id}">Reject</button></div></article>`).join('')||'<div class="designed-empty"><i>◎</i><h3>Your talent pool is ready</h3><p>Screen résumés to see ranked, evidence-backed candidates here.</p></div>'}</div>`}
function interviewPage(){const eligible=state.recruiter.candidates.filter(c=>c.score>=70||c.decision_status==='Selected');return `<div class="section-title"><div><div class="kicker">Interview workspace</div><h2>Upcoming conversations</h2></div><button class="primary" id="schedule-toggle">＋ Schedule interview</button></div><form id="interview-form" class="panel inline-form" hidden><select id="interview-candidate" required><option value="">Choose candidate</option>${eligible.map(c=>`<option value="${c.id}">${esc(c.candidate_name)} · ${esc(c.job_role)}</option>`).join('')}</select><select id="interview-type"><option>Technical</option><option>Behavioral</option><option>HR</option><option>Coding</option></select><input id="interview-date" type="datetime-local" required><select id="interview-mode"><option>Online</option><option>Physical</option></select><input id="interview-location" placeholder="Meeting link or location"><button class="primary">Schedule</button></form><div class="interview-layout"><section class="panel interview-list">${state.recruiter.interviews.map(i=>`<article><time><b>${i.scheduled_at?new Date(i.scheduled_at).toLocaleDateString('en',{day:'2-digit'}):'—'}</b><span>${i.scheduled_at?new Date(i.scheduled_at).toLocaleDateString('en',{month:'short'}):'TBD'}</span></time><div><h3>${esc(i.candidate_name||'Candidate')}</h3><p>${esc(i.job_role||'Role not assigned')} · ${esc(i.interview_type||'Interview')} · ${esc(i.mode||'')}</p></div><select data-interview-status="${i.id}">${['Scheduled','Completed','Cancelled'].map(s=>`<option ${i.status===s?'selected':''}>${s}</option>`).join('')}</select><button class="icon-action danger" data-delete-interview="${i.id}">⌫</button></article>`).join('')||'<div class="designed-empty"><i>◷</i><h3>No interviews scheduled</h3><p>Schedule a recommended candidate to begin the interview plan.</p></div>'}</section><aside class="panel interview-guide"><div class="kicker">Consistent interviews</div><h2>Make every conversation count.</h2><p>Use role-specific questions and a shared scoring method to keep decisions fair and focused.</p><div><span>01</span><b>Prepare questions</b></div><div><span>02</span><b>Score consistently</b></div><div><span>03</span><b>Capture the decision</b></div></aside></div>`}
function reportPage(){const s=state.recruiter.summary,roles=Object.entries(state.recruiter.candidates.reduce((a,c)=>(a[c.job_role||'Unassigned']=(a[c.job_role||'Unassigned']||0)+1,a),{}));return `<div class="stats report-stats">${[['Screened',s.candidates],['Shortlisted',s.shortlisted],['Selected',s.selected],['Interviews',s.scheduled_interviews]].map(([k,v])=>`<article><span>${k}</span><strong>${v}</strong><small>${s.candidates?Math.round(v/s.candidates*100):0}% of screened</small></article>`).join('')}</div><div class="report-grid"><section class="panel"><div class="kicker">Role-wise volume</div><h2>Candidates by job role</h2>${bars(roles,s.candidates)||'<div class="designed-empty"><i>↗</i><h3>No report data yet</h3><p>Screen candidates to populate role-wise insights.</p></div>'}</section><section class="panel conversion-card"><div class="kicker">Conversion</div><h2>Hiring funnel</h2><div class="funnel-row"><span>Screened</span><i style="--w:100%"></i><b>${s.candidates}</b></div><div class="funnel-row"><span>Shortlisted</span><i style="--w:${s.candidates?Math.max(8,s.shortlisted/s.candidates*100):0}%"></i><b>${s.shortlisted}</b></div><div class="funnel-row"><span>Selected</span><i style="--w:${s.candidates?Math.max(8,s.selected/s.candidates*100):0}%"></i><b>${s.selected}</b></div></section></div>`}
function offerPage(){const selected=state.recruiter.candidates.filter(c=>c.decision_status==='Selected');return `<section class="offer-hero"><div><div class="kicker pale">Offer studio</div><h2>Turn a hiring decision into a great welcome.</h2><p>Create polished, company-branded offer letters for one or many selected candidates.</p></div><div class="offer-hero-stat"><strong>${selected.length}</strong><span>ready for offer</span></div></section><div class="offer-progress"><span class="active"><i>1</i>Select candidates</span><span><i>2</i>Set terms</span><span><i>3</i>Generate letters</span></div><div class="offer-studio"><section class="panel offer-list modern-offer-list"><div class="panel-heading"><div><div class="kicker">Selected talent</div><h2>Choose recipients</h2></div><label class="select-all"><input type="checkbox" checked id="offer-all"> Select all</label></div>${selected.map(c=>`<article><input type="checkbox" data-offer-candidate value="${c.id}" checked><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><div><h3>${esc(c.candidate_name||c.filename)}</h3><p>${esc(c.job_role||'Role not assigned')}</p><small>Match score ${c.score}% · ${esc(c.email||'Email not captured')}</small></div><span class="status">Ready</span></article>`).join('')||'<div class="designed-empty"><i>◇</i><h3>No candidates ready for an offer</h3><p>Select a candidate after screening and interviews to prepare an offer here.</p><button class="secondary" data-quick="candidates">Review candidates</button></div>'}</section><aside class="panel offer-compose modern-offer-compose"><div class="kicker">Offer terms</div><h2>Letter details</h2><p>These terms are personalized for every selected recipient.</p><div class="offer-form-grid"><div class="wide"><label>Job title</label><input id="offer-role" value="${esc(selected[0]?.job_role||'')}" placeholder="Role offered"></div><div class="wide"><label>Annual compensation</label><input id="offer-salary" placeholder="e.g. ₹12,00,000 per annum"></div><div><label>Start date</label><input id="offer-start" type="date"></div><div><label>Accept by</label><input id="offer-deadline" type="date"></div><div class="wide"><label>Reporting manager</label><input id="offer-manager" placeholder="Manager name and title"></div></div><div class="offer-assurance"><i>✓</i><div><b>Company branded & personalized</b><span>Each PDF includes candidate, role, compensation, dates, and your organization identity.</span></div></div><button id="prepare-offers" class="primary full" ${selected.length?'':'disabled'}>Generate ${selected.length||''} offer letter${selected.length===1?'':'s'} →</button><small class="offer-note">Letters download together in one secure ZIP file.</small></aside></div>`}
function insightsPage(){return `<div class="insight-hero"><div><div class="kicker pale">AI hiring copilot</div><h2>Ask your hiring data.</h2><p>Explore candidate quality, skill gaps, pipeline health, and role-level patterns using the information already in your workspace.</p></div><div class="insight-orb">✦</div></div><div class="insight-grid"><section class="panel insight-prompts"><div class="kicker">Suggested questions</div><h2>Start with an insight</h2>${['Who are the strongest candidates for each active role?','Which skills are most commonly missing?','Where are candidates dropping out of the pipeline?','Summarize this week’s hiring progress.'].map(q=>`<button data-prompt="${esc(q)}"><span>${q}</span><i>→</i></button>`).join('')}</section><section class="panel ask-panel"><div class="assistant-mark">✦</div><h2>What would you like to know?</h2><p>Ask a question about jobs, candidates, interviews, or hiring progress.</p><textarea id="insight-question" rows="5" placeholder="Ask ICD Insights..."></textarea><button class="primary full" id="generate-insight">Generate insight →</button><div id="insight-answer" class="insight-answer" hidden></div><small>Answers are grounded in your organization’s workspace data.</small></section></div>`}
function bindRecruiter(){
 document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{state.page=b.dataset.quick;renderRecruiter()});
 const newJob=document.querySelector('#new-job');if(newJob)newJob.onclick=newJobModal;
 document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{const j=state.recruiter.jobs.find(x=>String(x.id)===b.dataset.screen);state.page='screening';renderRecruiter();document.querySelector('#job').value=j.id;document.querySelector('#role').value=j.title;document.querySelector('#details').value=[j.description,j.responsibilities,(j.required_skills||[]).join(', ')].filter(Boolean).join('\n\n')});
 document.querySelectorAll('[data-job-apps]').forEach(b=>b.onclick=()=>document.querySelector('#applications-panel')?.scrollIntoView({behavior:'smooth'}));
 document.querySelectorAll('[data-delete-job]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this job and its linked applications?'))return;try{await api('/api/jobs/'+b.dataset.deleteJob,{method:'DELETE'});await refresh('jobs','Job removed')}catch(e){note(e.message,'error')}});
 document.querySelectorAll('[data-app-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/applications/'+s.dataset.appStatus,{method:'PATCH',body:JSON.stringify({status:s.value})});await refresh('jobs','Application updated')}catch(e){note(e.message,'error')}});
 document.querySelectorAll('[data-delete-app]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this application?'))return;try{await api('/api/applications/'+b.dataset.deleteApp,{method:'DELETE'});await refresh('jobs','Application removed')}catch(e){note(e.message,'error')}});
 document.querySelectorAll('[data-view-candidate]').forEach(b=>b.onclick=()=>candidateModal(state.recruiter.candidates.find(c=>String(c.id)===b.dataset.viewCandidate)));
 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{await api('/api/candidates/'+b.dataset.id,{method:'PATCH',body:JSON.stringify({status:b.dataset.status})});await refresh('candidates','Candidate updated')}catch(e){note(e.message,'error')}});
 const toggle=document.querySelector('#schedule-toggle');if(toggle)toggle.onclick=()=>document.querySelector('#interview-form').hidden=!document.querySelector('#interview-form').hidden;
 const iform=document.querySelector('#interview-form');if(iform)iform.onsubmit=async e=>{e.preventDefault();const c=state.recruiter.candidates.find(x=>String(x.id)===document.querySelector('#interview-candidate').value),place=document.querySelector('#interview-location').value,mode=document.querySelector('#interview-mode').value;try{await api('/api/interviews',{method:'POST',body:JSON.stringify({candidate_id:c.id,candidate_name:c.candidate_name,candidate_email:c.email||'',job_role:c.job_role||'',interview_type:document.querySelector('#interview-type').value,scheduled_at:new Date(document.querySelector('#interview-date').value).toISOString(),mode,location:mode==='Physical'?place:'',meeting_link:mode==='Online'?place:''})});await refresh('interviews','Interview scheduled')}catch(err){note(err.message,'error')}};
 document.querySelectorAll('[data-interview-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/interviews/'+s.dataset.interviewStatus,{method:'PATCH',body:JSON.stringify({status:s.value})});await refresh('interviews','Interview updated')}catch(e){note(e.message,'error')}});
 document.querySelectorAll('[data-delete-interview]').forEach(b=>b.onclick=async()=>{try{await api('/api/interviews/'+b.dataset.deleteInterview,{method:'DELETE'});await refresh('interviews','Interview removed')}catch(e){note(e.message,'error')}});
 document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{document.querySelector('#insight-question').value=b.dataset.prompt;document.querySelector('#insight-question').focus()});
 const insight=document.querySelector('#generate-insight');if(insight)insight.onclick=async()=>{const q=document.querySelector('#insight-question').value.trim(),out=document.querySelector('#insight-answer');if(!q)return;insight.disabled=true;insight.textContent='Analysing workspace…';try{const r=await api('/api/insights',{method:'POST',body:JSON.stringify({question:q})});out.hidden=false;out.textContent=r.answer}catch(e){note(e.message,'error')}finally{insight.disabled=false;insight.textContent='Generate insight →'}};
 const offers=document.querySelector('#prepare-offers');if(offers)offers.onclick=async()=>{const ids=[...document.querySelectorAll('[data-offer-candidate]:checked')].map(x=>Number(x.value));if(!ids.length)return note('Choose at least one candidate','error');offers.disabled=true;offers.textContent='Preparing letters…';try{const response=await fetch('/api/offers.zip',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_ids:ids,job_title:document.querySelector('#offer-role').value,salary:document.querySelector('#offer-salary').value,start_date:document.querySelector('#offer-start').value,reporting_manager:document.querySelector('#offer-manager').value,acceptance_deadline:document.querySelector('#offer-deadline').value})});if(!response.ok){const e=await response.json();throw new Error(e.detail||'Could not prepare offers')}const blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ICD-offer-letters.zip';a.click();URL.revokeObjectURL(a.href);note('Offer letters prepared')}catch(e){note(e.message,'error')}finally{offers.disabled=false;offers.textContent='Prepare offer letters →'}};
 const offerAll=document.querySelector('#offer-all');if(offerAll)offerAll.onchange=()=>document.querySelectorAll('[data-offer-candidate]').forEach(x=>x.checked=offerAll.checked);
 const form=document.querySelector('#screen-form');if(form)form.onsubmit=async e=>{e.preventDefault();const fd=new FormData();fd.append('job_id',document.querySelector('#job').value);fd.append('job_role',document.querySelector('#role').value);fd.append('job_details',document.querySelector('#details').value);[...document.querySelector('#files').files].forEach(f=>fd.append('files',f));document.querySelector('#screen-status').textContent='Screening résumés in parallel…';try{const r=await api('/api/screen',{method:'POST',body:fd});note(`${r.processed} résumés screened`);await refresh('candidates')}catch(err){document.querySelector('#screen-status').textContent=err.message}};
 const jobSelect=document.querySelector('#job');if(jobSelect)jobSelect.onchange=()=>{const j=state.recruiter.jobs.find(x=>String(x.id)===jobSelect.value),preview=document.querySelector('#selected-role-preview');if(!j){if(preview)preview.innerHTML='<i>✎</i><div><b>Manual screening criteria</b><span>Enter a role title and detailed requirements below.</span></div>';return}document.querySelector('#role').value=j.title||'';document.querySelector('#details').value=[j.description,j.responsibilities,(j.required_skills||[]).length?'Required skills: '+j.required_skills.join(', '):''].filter(Boolean).join('\n\n');if(preview)preview.innerHTML=`<i>✓</i><div><b>${esc(j.title)}</b><span>${esc([j.department,j.location,j.employment_type,j.experience_level].filter(Boolean).join(' · '))}</span></div>`};
 const pickerTrigger=document.querySelector('#job-picker-trigger'),pickerMenu=document.querySelector('#job-picker-menu');if(pickerTrigger){pickerTrigger.onclick=e=>{e.stopPropagation();pickerMenu.hidden=!pickerMenu.hidden;pickerTrigger.classList.toggle('open',!pickerMenu.hidden);if(!pickerMenu.hidden)document.querySelector('#job-picker-search').focus()};document.querySelectorAll('[data-job-option]').forEach(option=>option.onclick=()=>{jobSelect.value=option.dataset.jobOption;jobSelect.dispatchEvent(new Event('change'));const j=state.recruiter.jobs.find(x=>String(x.id)===option.dataset.jobOption);pickerTrigger.querySelector('b').textContent=j?j.title:'Manual screening criteria';pickerTrigger.querySelector('small').textContent=j?([j.department,j.location].filter(Boolean).join(' · ')||'Active role'):'One-time benchmark';pickerMenu.hidden=true;pickerTrigger.classList.remove('open')});const search=document.querySelector('#job-picker-search');search.oninput=()=>document.querySelectorAll('#job-option-list .job-option').forEach(x=>x.hidden=!x.dataset.search.includes(search.value.toLowerCase().trim()));document.addEventListener('click',e=>{if(!document.querySelector('#job-picker')?.contains(e.target)){pickerMenu.hidden=true;pickerTrigger.classList.remove('open')}},{once:true})}
}
async function refresh(page,message){state.recruiter=await api('/api/bootstrap');state.page=page;renderRecruiter();if(message)note(message)}
function candidateModal(c){if(!c)return;const profile=typeof c.profile_json==='string'?JSON.parse(c.profile_json||'{}'):c.profile_json||{},score=typeof c.score_json==='string'?JSON.parse(c.score_json||'{}'):c.score_json||{};document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="candidate-modal"><section class="candidate-modal"><button class="modal-close" id="modal-close">×</button><div class="candidate-modal-head"><div class="candidate-monogram">${esc((c.candidate_name||'C')[0])}</div><div><div class="kicker">${esc(c.job_role||'Candidate')}</div><h2>${esc(c.candidate_name||c.filename)}</h2><p>${esc(c.email||'')} ${c.phone?'· '+esc(c.phone):''}</p></div><div class="score-ring large" style="--score:${c.score}"><b>${c.score}</b><span>match</span></div></div><div class="evidence-grid"><article><span>Skills match</span><b>${score.breakdown?.skills_match??c.skills_match??'—'}</b></article><article><span>Experience fit</span><b>${score.breakdown?.experience_fit??c.experience_fit??'—'}</b></article><article><span>Education fit</span><b>${score.breakdown?.education_fit??c.education_fit??'—'}</b></article></div><div class="modal-columns"><article><h3>Recruiter summary</h3><p>${esc(score.summary||c.recruiter_summary||'No summary available.')}</p><h3>Experience & education</h3><p>${esc(profile.years_experience||c.years_experience||'Not captured')} · ${esc(profile.education||c.education||'Not captured')}</p></article><article><h3>Matched skills</h3><div class="chips positive">${(c.matched_skills||[]).map(s=>`<span>${esc(s)}</span>`).join('')||'<span>None identified</span>'}</div><h3>Development gaps</h3><div class="chips gaps">${(c.gaps||[]).map(s=>`<span>${esc(s)}</span>`).join('')||'<span>No major gaps</span>'}</div></article></div><section class="ai-prep"><div><span>✦</span><div><h3>AI interview preparation</h3><p>Generate role-specific questions grounded in this candidate’s evidence.</p></div></div><button class="secondary" id="ai-questions">Generate questions</button><div id="question-output" hidden></div></section><label>Recruiter notes</label><textarea id="candidate-notes" rows="3">${esc(c.notes||'')}</textarea><div class="row"><button class="secondary" id="save-notes">Save notes</button><button class="primary" data-status="Selected" data-id="${c.id}">Select candidate</button></div></section></div>`);document.querySelector('#modal-close').onclick=()=>document.querySelector('#candidate-modal').remove();document.querySelector('#candidate-modal').onclick=e=>{if(e.target.id==='candidate-modal')e.currentTarget.remove()};document.querySelector('#ai-questions').onclick=async()=>{const b=document.querySelector('#ai-questions'),out=document.querySelector('#question-output');b.disabled=true;b.textContent='Preparing…';try{const r=await api('/api/interview-questions',{method:'POST',body:JSON.stringify({candidate_id:c.id})}),items=Array.isArray(r)?r:(r.questions||Object.values(r).flat().filter(x=>typeof x==='string'));out.hidden=false;out.innerHTML=`<h4>Suggested interview plan</h4><ol>${items.map(q=>`<li>${esc(typeof q==='string'?q:(q.question||JSON.stringify(q)))}</li>`).join('')}</ol>`}catch(e){note(e.message,'error')}finally{b.disabled=false;b.textContent='Regenerate questions'}};document.querySelector('#save-notes').onclick=async()=>{try{await api('/api/candidates/'+c.id,{method:'PATCH',body:JSON.stringify({notes:document.querySelector('#candidate-notes').value})});document.querySelector('#candidate-modal').remove();await refresh('candidates','Notes saved')}catch(e){note(e.message,'error')}};document.querySelector('#candidate-modal [data-status]').onclick=async()=>{await api('/api/candidates/'+c.id,{method:'PATCH',body:JSON.stringify({status:'Selected'})});document.querySelector('#candidate-modal').remove();await refresh('candidates','Candidate selected')}}
function newJobModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-shell" id="job-modal"><form class="candidate-modal job-form-modal" id="job-form"><button type="button" class="modal-close" id="job-close">×</button><div class="kicker">New opportunity</div><h2>Create a detailed job</h2><p>Publish a complete role that candidates can understand and trust.</p><div class="form-grid"><div><label>Role title</label><input name="title" required></div><div><label>Department</label><input name="department"></div><div><label>Location</label><input name="location" placeholder="Hybrid / Remote"></div><div><label>Employment type</label><select name="employment_type"><option>Full-time</option><option>Part-time</option><option>Contract</option><option>Internship</option></select></div><div class="wide"><label>Experience level</label><input name="experience_level" placeholder="e.g. 2–5 years"></div><div class="wide"><label>About the role</label><textarea name="description" rows="3"></textarea></div><div class="wide"><label>Responsibilities</label><textarea name="responsibilities" rows="3"></textarea></div><div class="wide"><label>Benefits</label><textarea name="benefits" rows="2"></textarea></div><div class="wide"><label>Required skills</label><input name="skills" placeholder="Python, FastAPI, PostgreSQL"></div></div><button class="primary full">Create and publish role →</button></form></div>`);document.querySelector('#job-close').onclick=()=>document.querySelector('#job-modal').remove();document.querySelector('#job-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.required_skills=(data.skills||'').split(',').map(x=>x.trim()).filter(Boolean);delete data.skills;try{await api('/api/jobs',{method:'POST',body:JSON.stringify(data)});document.querySelector('#job-modal').remove();await refresh('jobs','Job created')}catch(err){note(err.message,'error')}}}

const params=new URLSearchParams(location.search);params.has('candidate')?candidateEntry():params.has('recruiter')?recruiterGate():welcome();
